-- Initial editable content copied from the existing menu prototype. No live visit or QR is seeded.
do $seed$
declare tenant uuid; branch uuid; p jsonb; e jsonb; category text; content jsonb := $data${"products":[{"id":"rigatoni","name":"Rigatoni al pomodoro","description":"Rigatoni con salsa de tomate de la casa, albahaca fresca y queso parmesano.","category":"Platos fuertes","price":18900,"image":"https://images.unsplash.com/photo-1608897013039-887f21d8c804?auto=format&fit=crop&w=900&q=85","tag":"Favorito de la casa","vegetarian":true,"available":true,"allergens":["Leche","Gluten","Frutos secos"],"extras":[{"id":"pan","name":"Pan de masa madre extra","price":3500}]},{"id":"pasta","name":"Pasta artesanal al pesto","description":"Pasta artesanal, pesto de albahaca, parmesano y un toque de aceite de oliva.","category":"Platos fuertes","price":23500,"image":"https://images.unsplash.com/photo-1473093295043-cdd812d0e601?auto=format&fit=crop&w=900&q=85","tag":"El más pedido","vegetarian":true,"available":true,"allergens":["Gluten","Leche","Huevo","Frutos secos"],"extras":[{"id":"pollo","name":"Pollo a la parrilla","price":6500},{"id":"parmesano","name":"Parmesano extra","price":2500}]},{"id":"burger","name":"Hamburguesa del Olivo","description":"Res a la parrilla, queso cheddar, cebolla caramelizada y papas crujientes.","category":"Platos fuertes","price":24900,"image":"https://images.unsplash.com/photo-1568901346375-23c9450c58cd?auto=format&fit=crop&w=900&q=85","available":true,"allergens":["Gluten","Leche","Huevo"],"extras":[{"id":"queso","name":"Queso cheddar extra","price":2500},{"id":"tocino","name":"Tocino crujiente","price":3500}]},{"id":"salad","name":"Ensalada mediterránea","description":"Hojas frescas, tomates cherry, pepino, aceitunas, queso feta y vinagreta de limón.","category":"Ensaladas","price":17500,"image":"https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=900&q=85","vegetarian":true,"available":true,"allergens":["Leche"],"extras":[{"id":"pollo","name":"Pollo a la parrilla","price":6500}]},{"id":"salmon","name":"Salmón a la parrilla","description":"Salmón con costra de hierbas, vegetales asados y mantequilla de limón.","category":"Platos fuertes","price":32900,"image":"https://images.unsplash.com/photo-1467003909585-2f8a72700288?auto=format&fit=crop&w=900&q=85","tag":"Recomendación del chef","available":true,"allergens":["Pescado","Leche"],"extras":[{"id":"verduras","name":"Vegetales extra","price":4500}]},{"id":"cake","name":"Pastel de chocolate","description":"Chocolate intenso, centro suave y frutos rojos. El final que te mereces.","category":"Postres","price":11900,"image":"https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=900&q=85","vegetarian":true,"available":true,"allergens":["Gluten","Leche","Huevo"],"extras":[{"id":"helado","name":"Helado de vainilla","price":3000}]},{"id":"lemonade","name":"Limonada de la casa","description":"Limón recién exprimido, hierbabuena y agua mineral. Fresca y natural.","category":"Bebidas","price":6500,"image":"https://images.unsplash.com/photo-1544145945-f90425340c7e?auto=format&fit=crop&w=900&q=85","vegetarian":true,"available":true,"allergens":[],"extras":[]},{"id":"toast","name":"Tostada de aguacate","description":"Masa madre tostada, aguacate, huevo pochado y semillas de temporada.","category":"Entradas","price":15900,"image":"https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=900&q=85","vegetarian":true,"available":false,"allergens":["Gluten","Huevo","Sésamo"],"extras":[]}],"categories":["Entradas","Platos fuertes","Ensaladas","Postres","Bebidas"]}$data$::jsonb;
begin
 insert into public.menu_businesses(slug,name,tagline) values('el-olivo','El Olivo','cocina de temporada') returning id into tenant;
 insert into public.menu_branches(tenant_id,slug,name,location,published,published_at) values(tenant,'el-olivo-roma','Roma Norte','Roma Norte, CDMX',true,now()) returning id into branch;
 for category in select jsonb_array_elements_text(content->'categories') loop
  insert into public.menu_categories(branch_id,id,name,sort_order) values(branch,category,category,(select ordinality::integer from jsonb_array_elements_text(content->'categories') with ordinality t where value=category));
 end loop;
 for p in select * from jsonb_array_elements(content->'products') loop
  insert into public.menu_products(branch_id,id,category_id,name,description,price_cents,image_url,tag,vegetarian,available,allergens,sort_order)
  values(branch,p->>'id',p->>'category',p->>'name',p->>'description',(p->>'price')::integer,p->>'image',p->>'tag',coalesce((p->>'vegetarian')::boolean,false),(p->>'available')::boolean,array(select jsonb_array_elements_text(p->'allergens')),(select ordinality::integer from jsonb_array_elements(content->'products') with ordinality t where value=p));
  for e in select * from jsonb_array_elements(p->'extras') loop
   insert into public.menu_product_extras(branch_id,product_id,id,name,price_cents) values(branch,p->>'id',e->>'id',e->>'name',(e->>'price')::integer);
  end loop;
 end loop;
end $seed$;
